import {money,cents,today,categoryList,fundingAccount} from './domain.mjs';
import {createClaim,receiveClaim,reverseClaimPayment,cancelClaim,claimRemaining,partyRemaining,equalShares,spendable,setReserve,settlementData} from './settlement-core.mjs';
export function createSettlementUI(c){
  const {E,I,toast,openSheet}=c,$=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
  const field=(label,id,value='',type='text',extra='')=>`<label class="field">${label}<input id="${id}" type="${type}" value="${E(value)}" ${extra}></label>`;
  const select=(label,id,rows,value)=>`<label class="field">${label}<select id="${id}">${rows.map(([k,v])=>`<option value="${E(k)}" ${value===k?'selected':''}>${E(v)}</option>`).join('')}</select></label>`;
  function finish(next,message){if(c.commit(next)){c.render();$('#sheet').close();if(message)toast(message);return true;}return false;}
  const name=id=>c.getState().accounts.find(a=>a.id===id)?.name||'未指定';
  function page(){const state=c.getState(),claims=settlementData(state).claims.filter(v=>c.getBook()==='all'||v.bookId===c.getBook());return `<div class="page-title"><div><div class="eyebrow">SHARE THE BILL, KEEP IT CLEAR</div><h1>幫忙先付，也記得收回。</h1><p class="subtitle">自己的花費、替別人墊的錢，分開看清楚。</p></div><button class="primary" id="claim-add">${I('plus')}新增代墊／分帳</button></div><div class="stat-grid">${[['待收回代墊',money(claims.reduce((n,v)=>n+claimRemaining(v),0))],['尚未結清',claims.filter(v=>claimRemaining(v)>0).length+' 筆'],['已結清',claims.filter(v=>!claimRemaining(v)).length+' 筆']].map(([l,n])=>`<div class="card"><div class="card-label">${l}</div><div class="metric-value sensitive">${E(n)}</div></div>`).join('')}</div><div class="notice">代墊部分記成轉帳至「應收代墊款」，只有自己負擔部分算支出。收回代墊記轉帳，不增加收入。若之前已記整筆支出，請在新增時選擇拆分該筆紀錄。</div><div class="card" style="margin-top:20px">${claims.length?claims.map(v=>`<div class="due-row"><div><strong>${E(v.name)}</strong><small>${E(v.date)} · ${E(name(v.source))} · 總付 ${money(v.total)}／自己 ${money(v.selfShare)}<br>${v.parties.map(p=>E(p.name)+' 待還 '+money(partyRemaining(v,p.id))).join(' · ')}</small></div><strong class="sensitive">${money(claimRemaining(v))}</strong><button class="secondary" data-claim-detail="${E(v.id)}">${claimRemaining(v)?'記錄收款':'查看紀錄'}</button></div>`).join(''):'<div class="empty-state">還沒有代墊。聚餐、出差或事業代購，都可以在這裡記錄。</div>'}</div>`;}
  function add(){const state=c.getState();openSheet('新增代墊／分帳',`<form id="claim-form">${field('項目名稱','claim-name','','text','required maxlength="200" placeholder="例如：聚餐、出差住宿"')}<div class="row">${field('實付總額（NT$）','claim-total','','number','required min="0.01" step="0.01"')}${field('付款日期','claim-date',today(),'date','required')}</div>${select('實際付款帳戶','claim-source',state.accounts.filter(a=>a.kind!=='receivable').map(a=>[a.id,a.name]),state.accounts[0].id)}${select('所屬帳本','claim-book',state.features.books.map(b=>[b.id,b.name]),c.getBook()==='all'?'personal':c.getBook())}${select('自己的支出分類','claim-category',categoryList(state).map(v=>[v,v]),'其他')}${field('對方姓名（逗號分隔，不含自己）','claim-names','','text','required maxlength="1000" placeholder="例如：小王、小美"')}<button type="button" class="secondary" id="claim-equal">按人數平均分攤（包含自己）</button><div class="row" style="margin-top:16px">${field('自己負擔（NT$）','claim-self','','number','required min="0" step="0.01"')}</div><p class="help">平均分攤會精確分配到分；也可自行修改每人金額。全部加總必須等於實付總額。</p><div id="claim-party-amounts"></div>${select('若已記整筆支出，可拆分原紀錄','claim-existing',[['','新增記帳（尚未記過這筆付款）'],...state.transactions.filter(t=>t.type==='expense'&&!t.origin&&!(state.invoices||[]).some(v=>v.txId===t.id)).slice(0,200).map(t=>[t.id,t.date+' · '+t.note+' · '+money(t.amount)])],'')}<p class="help">拆分既有支出必須同金額、日期及付款帳戶；已連結發票或分期的支出請先核對，不在此直接拆分。若由既有支出拆分，撤銷分帳時會恢復原支出。</p><div class="inline-error" id="claim-error" role="alert"></div><button class="primary full">確認建立代墊</button></form>`);
    let names=[];function makeFields(amounts=[]){names=$('#claim-names').value.split(/[，,]/).map(s=>s.trim()).filter(Boolean);$('#claim-party-amounts').innerHTML=names.map((n,i)=>field(E(n)+' 分攤（NT$）','claim-party-'+i,amounts[i]===undefined?'':amounts[i]/100,'number','required min="0.01" step="0.01"')).join('');}
    $('#claim-names').onchange=()=>makeFields();$('#claim-equal').onclick=()=>{try{const result=equalShares(cents($('#claim-total').value),$('#claim-names').value.split(/[，,]/).map(s=>s.trim()).filter(Boolean));$('#claim-self').value=result.selfShare/100;makeFields(result.parties.map(p=>p.amount));}catch(e){$('#claim-error').textContent=e.message;}};
    $('#claim-form').onsubmit=e=>{e.preventDefault();try{const typed=$('#claim-names').value.split(/[，,]/).map(s=>s.trim()).filter(Boolean);if(JSON.stringify(typed)!==JSON.stringify(names)){makeFields();throw Error('請填寫每位分攤金額，或按平均分攤');}finish(createClaim(c.getState(),{name:$('#claim-name').value.trim(),date:$('#claim-date').value,total:cents($('#claim-total').value),selfShare:cents($('#claim-self').value),source:$('#claim-source').value,category:$('#claim-category').value,bookId:$('#claim-book').value,existingTxId:$('#claim-existing').value||null,parties:names.map((name,i)=>({name,amount:cents($('#claim-party-'+i).value)}))}),'代墊已建立，只有自己負擔計入支出');}catch(err){$('#claim-error').textContent=err.message;}};
  }
  function detail(id){const v=settlementData(c.getState()).claims.find(v=>v.id===id);if(!v)return;openSheet('代墊收款紀錄',`<p class="help">${E(v.name)} · ${E(v.date)} · 尚待收回 ${money(claimRemaining(v))}</p>${v.parties.map(p=>`<div class="due-row"><strong>${E(p.name)}</strong><span class="sensitive">${money(partyRemaining(v,p.id))}</span><button class="secondary" data-claim-receive="${E(p.id)}" ${partyRemaining(v,p.id)?'':'disabled'}>記錄還款</button></div>`).join('')}<h3 style="margin-top:24px">實際收到的款項</h3>${v.payments.map(p=>`<div class="due-row"><div><strong>${E(v.parties.find(v=>v.id===p.partyId)?.name)}</strong><small>${E(p.date)} · ${E(name(p.target))} · ${money(p.amount)}</small></div><button class="text-btn" data-claim-reverse="${E(p.id)}">撤銷這次記帳</button></div>`).join('')||'<p class="help">尚未收款。</p>'}<button class="secondary danger" id="claim-cancel" ${v.payments.length?'disabled':''} style="margin-top:20px">撤銷整筆代墊記帳</button><p class="help">以上只管理帳目，不會替你收款或通知他人。</p>`);$$('[data-claim-receive]').forEach(b=>b.onclick=()=>receiveForm(id,b.dataset.claimReceive));$$('[data-claim-reverse]').forEach(b=>b.onclick=()=>{if(confirm('撤銷這筆收款記帳？不會退回實際收到的款項。'))finish(reverseClaimPayment(c.getState(),id,b.dataset.claimReverse),'收款記帳已撤銷');});$('#claim-cancel').onclick=()=>{if(confirm('撤銷代墊與自己負擔的記帳？若由既有支出拆分建立，會恢復原支出。'))finish(cancelClaim(c.getState(),id),'代墊記帳已撤銷');};}
  function receiveForm(id,partyId){const v=settlementData(c.getState()).claims.find(v=>v.id===id),p=v.parties.find(v=>v.id===partyId),state=c.getState();openSheet('記錄實際收到還款',`<form id="claim-receive-form"><p class="help">${E(v.name)} · ${E(p.name)}</p>${field('本次收到（NT$）','claim-received',partyRemaining(v,partyId)/100,'number','required min="0.01" step="0.01"')}${select('實際收款帳戶','claim-target',state.accounts.filter(a=>['cash','bank','mobile'].includes(state.accounts.find(x=>x.id===fundingAccount(state,a.id))?.kind)).map(a=>[a.id,a.name]),state.accounts.find(a=>a.kind==='bank')?.id||state.accounts[0].id)}${field('實際收款日','claim-received-date',today(),'date','required')}<div class="inline-error" id="claim-receive-error" role="alert"></div><button class="primary full">確認收款（記為轉帳）</button></form>`);$('#claim-receive-form').onsubmit=e=>{e.preventDefault();try{finish(receiveClaim(c.getState(),id,{partyId,amount:cents($('#claim-received').value),date:$('#claim-received-date').value,target:$('#claim-target').value}),'代墊已收回，未增加收入');}catch(err){$('#claim-receive-error').textContent=err.message;}};}
  function availablePage(){const state=c.getState(),v=spendable(state);return `<div class="page-title"><div><div class="eyebrow">MAKE ROOM FOR WHAT'S NEXT</div><h1>接下來，可以安排多少？</h1><p class="subtitle">依未來30天已知支出與你的保留金計算。</p></div></div><div class="card hero-card"><div class="card-label">依已知資料估算的可花金額</div><div class="large-amount sensitive"><span>NT$</span>${money(v.available).slice(3)}</div><p class="help">${v.available<0?'已知支出與保留金超過目前流動資金，請先核對待繳排程。':'此數字只依已記錄的帳目與排程估算。'}</p></div><div class="stat-grid" style="margin-top:20px">${[['目前流動資金',v.initial],['未來30天已知流出',v.outflows],['預留不動用金額',v.reserve]].map(([l,n])=>`<div class="card"><div class="card-label">${l}</div><div class="metric-value sensitive">${money(n)}</div></div>`).join('')}</div><div class="card"><h2>自己設定保留金</h2><form id="reserve-form">${field('希望保留不動用（NT$）','reserve-amount',v.reserve/100,'number','required min="0" step="0.01"')}<button class="primary">儲存保留金</button></form><p class="help">計算方式：目前現金／銀行／獨立錢包 − 未來30天已知淨流出項目 − 保留金。尚未入帳的薪資、退款與代墊還款不先加進來。內部轉帳不重複扣除。</p><p class="help">尚待收回代墊 ${money(v.uncollected)} 不屬於可花現金。信用額度、應收款也不列入流動資金。</p>${v.unscheduled.length?'<div class="notice">以下帳戶的待還款尚未完全涵蓋於未來30天排程：'+v.unscheduled.map(a=>E(a.name)).join('、')+'。請補上待繳日期與金額，避免高估可花金額。</div>':''}<p class="help">這不是保證可支出的額度；尚未記錄的消費、稅費、未排程待繳款不在計算內。過期未確認的排程會暫列今天，請先完成對帳。</p></div>`;}
  function homePanel(){const v=spendable(c.getState());return `<div class="card available-strip" style="margin-bottom:24px"><div><small>未來30天 · 扣除已知流出與保留金</small><strong class="sensitive">可花估算 ${money(v.available)}</strong></div><button class="secondary" data-page="available">查看計算</button><button class="text-btn" data-page="settlements">代墊分帳</button></div>`;}
  function bind(){$('#claim-add')?.addEventListener('click',add);$$('[data-claim-detail]').forEach(b=>b.onclick=()=>detail(b.dataset.claimDetail));$('#reserve-form')?.addEventListener('submit',e=>{e.preventDefault();try{finish(setReserve(c.getState(),cents($('#reserve-amount').value)),'保留金已儲存');}catch(err){toast(err.message);}});}
  return {page,availablePage,homePanel,bind};
}
